_W = 1024
_H = 1024
PAPER = (247, 243, 232)
INK = (17, 17, 17)
RED = (178, 28, 28)
BLUE = (29, 78, 176)
TEAL = (13, 110, 110)
GREY = (90, 86, 76)
LIGHT = (233, 227, 210)
GOLD = (176, 124, 20)


# ------------------------------------------------------------------- canvas
class Canvas:
    def __init__(self, w, h, bg):
        self.w = w
        self.h = h
        self.px = bytearray(w * h * 3)
        self.fill_rect(0, 0, w, h, bg)

    def set(self, x, y, rgb):
        if 0 <= x < self.w and 0 <= y < self.h:
            i = (y * self.w + x) * 3
            self.px[i], self.px[i + 1], self.px[i + 2] = rgb

    def blend(self, x, y, rgb, a):
        """Blend rgb over the pixel with coverage a (0..255)."""
        if a <= 0 or not (0 <= x < self.w and 0 <= y < self.h):
            return
        if a >= 255:
            self.set(x, y, rgb)
            return
        i = (y * self.w + x) * 3
        inv = 255 - a
        self.px[i] = (rgb[0] * a + self.px[i] * inv) // 255
        self.px[i + 1] = (rgb[1] * a + self.px[i + 1] * inv) // 255
        self.px[i + 2] = (rgb[2] * a + self.px[i + 2] * inv) // 255

    def fill_rect(self, x, y, w, h, rgb):
        x0 = max(0, x)
        y0 = max(0, y)
        x1 = min(self.w, x + w)
        y1 = min(self.h, y + h)
        if x1 <= x0 or y1 <= y0:
            return
        row = bytes(rgb) * (x1 - x0)
        for yy in range(y0, y1):
            i = (yy * self.w + x0) * 3
            self.px[i:i + len(row)] = row

    def hline(self, x, y, w, rgb, t=1):
        self.fill_rect(x, y, w, t, rgb)

    def vline(self, x, y, h, rgb, t=1):
        self.fill_rect(x, y, t, h, rgb)

    def line(self, x0, y0, x1, y1, rgb, t=1):
        dx = abs(x1 - x0)
        dy = -abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx + dy
        while True:
            self.fill_rect(x0 - t // 2, y0 - t // 2, t, t, rgb)
            if x0 == x1 and y0 == y1:
                break
            e2 = 2 * err
            if e2 >= dy:
                err += dy
                x0 += sx
            if e2 <= dx:
                err += dx
                y0 += sy

    def circle(self, cx, cy, r, rgb):
        for yy in range(cy - r, cy + r + 1):
            dy = yy - cy
            dx = int((r * r - dy * dy) ** 0.5)
            self.fill_rect(cx - dx, yy, 2 * dx + 1, 1, rgb)

    def ring(self, cx, cy, r, rgb, t=2):
        for yy in range(cy - r, cy + r + 1):
            dy = yy - cy
            outer = int((r * r - dy * dy) ** 0.5)
            inner_r = max(0, r - t)
            inner = int((inner_r * inner_r - dy * dy) ** 0.5) if abs(dy) < inner_r else 0
            self.fill_rect(cx - outer, yy, outer - inner, 1, rgb)
            self.fill_rect(cx + inner + 1, yy, outer - inner, 1, rgb)

    def ellipse(self, cx, cy, rx, ry, rgb):
        for yy in range(cy - ry, cy + ry + 1):
            dy = (yy - cy) / float(ry)
            dx = int(rx * (1 - dy * dy) ** 0.5)
            self.fill_rect(cx - dx, yy, 2 * dx + 1, 1, rgb)

    def poly(self, pts, rgb):
        """Scanline fill of a simple polygon."""
        if len(pts) < 3:
            return
        ys = [p[1] for p in pts]
        for y in range(max(0, min(ys)), min(self.h, max(ys) + 1)):
            xs = []
            n = len(pts)
            for i in range(n):
                x0, y0 = pts[i]
                x1, y1 = pts[(i + 1) % n]
                if (y0 <= y < y1) or (y1 <= y < y0):
                    xs.append(x0 + (y - y0) * (x1 - x0) / float(y1 - y0))
            xs.sort()
            for k in range(0, len(xs) - 1, 2):
                self.fill_rect(int(xs[k]), y, int(xs[k + 1]) - int(xs[k]) + 1, 1, rgb)


# --------------------------------------------------------------------- fonts
_FONTS = None
_GLYPH_CACHE = {}


def _load_fonts():
    global _FONTS
    if _FONTS is None:
        raw = zlib.decompress(base64.b85decode(FONT_BLOB.encode("ascii")))
        _FONTS = json.loads(raw.decode("utf-8"))
    return _FONTS


def _scale_glyph(face, ch, size):
    """Return (w, h, advance, top, left, coverage bytes) at `size` px."""
    key = (face, ch, size)
    g = _GLYPH_CACHE.get(key)
    if g is not None:
        return g
    fonts = _load_fonts()
    master = fonts["size"]
    entry = fonts["fonts"][face].get(ch)
    if entry is None:
        entry = fonts["fonts"][face].get("?")
    w, h, adv, base, ox, comp = entry
    s = size / float(master)
    sw = max(1, int(round(w * s)))
    sh = max(1, int(round(h * s)))
    if not comp:
        g = (sw, sh, max(1, int(round(adv * s))), int(round(base * s)),
             int(round(ox * s)), bytes(sw * sh))
        _GLYPH_CACHE[key] = g
        return g
    src = zlib.decompress(base64.b85decode(comp.encode("ascii")))
    # Area-average downscale (nearest when scaling up).
    out = bytearray(sw * sh)
    if s >= 1.0:
        for oy in range(sh):
            sy = min(h - 1, int(oy / s))
            for oxp in range(sw):
                sx = min(w - 1, int(oxp / s))
                out[oy * sw + oxp] = src[sy * w + sx]
    else:
        for oy in range(sh):
            y0 = int(oy / s)
            y1 = max(y0 + 1, int((oy + 1) / s))
            for oxp in range(sw):
                x0 = int(oxp / s)
                x1 = max(x0 + 1, int((oxp + 1) / s))
                total = 0
                cnt = 0
                for yy in range(y0, min(h, y1)):
                    rowbase = yy * w
                    for xx in range(x0, min(w, x1)):
                        total += src[rowbase + xx]
                        cnt += 1
                out[oy * sw + oxp] = total // max(1, cnt)
    g = (sw, sh, max(1, int(round(adv * s))), int(round(base * s)),
         int(round(ox * s)), bytes(out))
    _GLYPH_CACHE[key] = g
    return g


def text_width(text, face, size):
    total = 0
    for ch in text:
        total += _scale_glyph(face, ch, size)[2]
    return total


def draw_text(cv, x, baseline, text, face, size, rgb, align="l"):
    if align == "c":
        x -= text_width(text, face, size) // 2
    elif align == "r":
        x -= text_width(text, face, size)
    cx = x
    for ch in text:
        if ch == " ":
            cx += _scale_glyph(face, ch, size)[2]
            continue
        w, h, adv, base, ox, cov = _scale_glyph(face, ch, size)
        gx = cx + ox
        gy = baseline - base
        for yy in range(h):
            row = yy * w
            py = gy + yy
            if py < 0 or py >= cv.h:
                continue
            for xx in range(w):
                a = cov[row + xx]
                if a:
                    cv.blend(gx + xx, py, rgb, a)
        cx += adv
    return cx - x


def wrap_text(text, face, size, max_w):
    lines = []
    for para in text.split("\n"):
        words = para.split()
        if not words:
            lines.append("")
            continue
        cur = words[0]
        for wd in words[1:]:
            trial = cur + " " + wd
            if text_width(trial, face, size) <= max_w:
                cur = trial
            else:
                lines.append(cur)
                cur = wd
        lines.append(cur)
    return lines


def draw_para(cv, x, y, text, face, size, rgb, max_w, leading=None):
    if leading is None:
        leading = int(size * 1.32)
    yy = y + size
    for ln in wrap_text(text, face, size, max_w):
        draw_text(cv, x, yy, ln, face, size, rgb)
        yy += leading
    return yy


# ----------------------------------------------------------------------- png
def write_png(cv, path):
    raw = bytearray()
    stride = cv.w * 3
    for y in range(cv.h):
        raw.append(0)
        raw += cv.px[y * stride:(y + 1) * stride]
    comp = zlib.compress(bytes(raw), 9)

    def chunk(tag, data):
        c = struct.pack(">I", len(data)) + tag + data
        return c + struct.pack(">I", binascii.crc32(tag + data) & 0xFFFFFFFF)

    png = b"\x89PNG\r\n\x1a\n"
    png += chunk(b"IHDR", struct.pack(">IIBBBBB", cv.w, cv.h, 8, 2, 0, 0, 0))
    png += chunk(b"IDAT", comp)
    png += chunk(b"IEND", b"")
    with open(path, "wb") as f:
        f.write(png)
    return len(png)


# -------------------------------------------------------------- illustrations
def draw_globe(cv, cx, cy, r):
    """Blue globe with green land, white meridians and a red crack."""
    cv.circle(cx, cy, r, (38, 92, 168))
    cv.circle(cx, cy, r - 2, (52, 120, 200))
    # land masses
    cv.ellipse(cx - r // 3, cy - r // 3, r // 2, r // 3, (46, 140, 78))
    cv.ellipse(cx + r // 3, cy + r // 4, r // 3, r // 4, (46, 140, 78))
    cv.ellipse(cx + r // 5, cy - r // 2, r // 4, r // 5, (60, 160, 90))
    cv.ellipse(cx - r // 2, cy + r // 2, r // 3, r // 4, (46, 140, 78))
    # meridian outlines: light ring over a blue disc leaves a thin arc
    for k in (1, 2):
        rx = r * k // 3
        cv.ellipse(cx, cy, rx, r, (220, 230, 245))
        cv.ellipse(cx, cy, max(1, rx - 2), r - 2, (52, 120, 200))
    cv.ellipse(cx, cy, r, r // 3, (220, 230, 245))
    cv.ellipse(cx, cy, r - 2, max(1, r // 3 - 2), (52, 120, 200))
    # re-draw land on top of the meridian wash
    cv.ellipse(cx - r // 3, cy - r // 3, r // 2, r // 3, (46, 140, 78))
    cv.ellipse(cx + r // 3, cy + r // 4, r // 3, r // 4, (46, 140, 78))
    cv.ring(cx, cy, r, (17, 17, 17), 3)
    # the crack: jagged red line across the globe
    pts = [(cx - r + 8, cy - r // 3), (cx - r // 2, cy - r // 6),
           (cx - r // 4, cy + r // 6), (cx, cy - r // 8),
           (cx + r // 3, cy + r // 4), (cx + r - 6, cy + r // 2)]
    for a, b in zip(pts, pts[1:]):
        cv.line(a[0], a[1], b[0], b[1], RED, 4)
    # the crack: jagged red line across the globe
    pts = [(cx - r + 8, cy - r // 3), (cx - r // 2, cy - r // 6),
           (cx - r // 4, cy + r // 6), (cx, cy - r // 8),
           (cx + r // 3, cy + r // 4), (cx + r - 6, cy + r // 2)]
    for a, b in zip(pts, pts[1:]):
        cv.line(a[0], a[1], b[0], b[1], RED, 4)


def draw_ship(cv, x, y, w, h):
    """Warship at sea with a drone above it."""
    sea = y + h - 18
    cv.fill_rect(x, sea, w, 18, (52, 120, 200))
    cv.fill_rect(x, sea, w, 3, (120, 180, 235))
    # hull
    cv.poly([(x + 8, sea - 14), (x + w - 8, sea - 14), (x + w - 26, sea),
             (x + 22, sea)], (90, 96, 104))
    cv.fill_rect(x + 14, sea - 26, w - 40, 12, (70, 76, 84))
    cv.line(x + w // 2, sea - 26, x + w // 2, sea - 44, (17, 17, 17), 3)
    cv.poly([(x + w // 2, sea - 44), (x + w // 2 + 22, sea - 34),
             (x + w // 2, sea - 34)], RED)
    # drone
    dx, dy = x + w - 26, y + 8
    cv.fill_rect(dx - 10, dy, 20, 4, INK)
    cv.circle(dx, dy + 2, 4, INK)
    cv.line(dx, dy + 4, dx - 6, dy + 12, INK, 2)
    # waves
    for wx in range(x + 4, x + w - 4, 18):
        cv.line(wx, sea + 8, wx + 9, sea + 5, (220, 235, 250), 2)


def draw_chip(cv, x, y, w, h):
    """AI chip with pins and a rising arrow."""
    cv.fill_rect(x, y, w, h, (24, 24, 30))
    cv.fill_rect(x + 6, y + 6, w - 12, h - 12, (52, 120, 200))
    for i in range(5):
        px = x + 12 + i * ((w - 24) // 4)
        cv.fill_rect(px, y - 6, 4, 6, (180, 180, 190))
        cv.fill_rect(px, y + h, 4, 6, (180, 180, 190))
        py = y + 12 + i * ((h - 24) // 4)
        cv.fill_rect(x - 6, py, 6, 4, (180, 180, 190))
        cv.fill_rect(x + w, py, 6, 4, (180, 180, 190))
    cv.fill_rect(x + w // 2 - 14, y + h // 2 - 14, 28, 28, (247, 243, 232))
    draw_text(cv, x + w // 2, y + h // 2 + 8, "AI", "sans_b", 20, (24, 24, 30),
              align="c")
    # rising arrow
    cv.line(x + 8, y + h - 12, x + w // 2, y + 12, (46, 200, 120), 3)
    cv.line(x + w // 2, y + 12, x + w - 8, y + 12, (46, 200, 120), 3)
    cv.line(x + w - 8, y + 12, x + w - 8, y + 24, (46, 200, 120), 3)


def draw_tanker(cv, x, y, w, h):
    """Oil tanker in a strait with a mine."""
    sea = y + h - 16
    cv.fill_rect(x, sea, w, 16, (52, 120, 200))
    cv.poly([(x + 6, sea - 16), (x + w - 6, sea - 16), (x + w - 18, sea),
             (x + 16, sea)], (178, 28, 28))
    cv.fill_rect(x + w // 2 - 8, sea - 34, 16, 18, (247, 243, 232))
    cv.line(x + w // 2 - 4, sea - 34, x + w // 2 - 4, sea - 46, INK, 3)
    # mine: spiky circle
    mx, my = x + w - 16, y + 12
    cv.circle(mx, my, 9, INK)
    for dx, dy in ((0, -13), (0, 13), (-13, 0), (13, 0), (-9, -9), (9, -9),
                   (-9, 9), (9, 9)):
        cv.line(mx, my, mx + dx, my + dy, INK, 2)
    # flame
    cv.poly([(x + 10, y + 16), (x + 18, y + 2), (x + 26, y + 16)],
            (240, 140, 20))


def draw_shield(cv, x, y, w, h):
    """NATO-style shield with a compass star, centred in its box."""
    cx = x + w // 2
    hw, hh = 52, h // 2
    cy = y + h // 2
    cv.poly([(cx - hw, y + 4), (cx + hw, y + 4),
             (cx + hw, y + hh), (cx, y + h - 2),
             (cx - hw, y + hh)], BLUE)
    cv.poly([(cx - hw + 6, y + 10), (cx + hw - 6, y + 10),
             (cx + hw - 6, y + hh), (cx, y + h - 9),
             (cx - hw + 6, y + hh)], (247, 243, 232))
    cv.poly([(cx, cy - 16), (cx + 4, cy - 4), (cx + 16, cy), (cx + 4, cy + 4),
             (cx, cy + 16), (cx - 4, cy + 4), (cx - 16, cy), (cx - 4, cy - 4)],
            BLUE)
    cv.circle(cx, cy, 4, RED)


def draw_bars(cv, x, y, w, h):
    """Rising market bars."""
    n = 6
    bw = w // (n * 2)
    vals = [0.35, 0.45, 0.42, 0.62, 0.78, 1.0]
    for i, v in enumerate(vals):
        bh = int(h * v)
        col = (46, 140, 78) if i < 5 else (178, 28, 28)
        cv.fill_rect(x + i * 2 * bw + bw // 2, y + h - bh, bw, bh, col)
    cv.line(x, y + h - int(h * 0.95), x + w, y + 4, (17, 17, 17), 3)
    cv.poly([(x + w - 10, 4 + y), (x + w, y + 12), (x + w - 12, y + 12)],
            INK)


def draw_ball(cv, x, y, w, h):
    """Football."""
    cx, cy, r = x + w // 2, y + h // 2, min(w, h) // 2 - 2
    cv.circle(cx, cy, r, (247, 243, 232))
    cv.ring(cx, cy, r, INK, 3)
    cv.poly([(cx, cy - 10), (cx + 10, cy - 3), (cx + 6, cy + 9),
             (cx - 6, cy + 9), (cx - 10, cy - 3)], INK)
    for ang in (90, 210, 330):
        import math
        rad = math.radians(ang)
        ex = int(cx + (r - 2) * math.cos(rad))
        ey = int(cy - (r - 2) * math.sin(rad))
        cv.line(cx, cy, ex, ey, INK, 2)


def draw_dove(cv, x, y, w, h):
    """Olive branch."""
    cv.line(x + 6, y + h - 8, x + w - 6, y + 8, (46, 140, 78), 3)
    for i in range(4):
        lx = x + 12 + i * ((w - 24) // 3)
        ly = y + h - 16 - i * ((h - 24) // 3)
        cv.ellipse(lx, ly, 10, 5, (60, 160, 90))
        cv.ellipse(lx + 4, ly - 12, 9, 5, (46, 140, 78))


def draw_gavel(cv, x, y, w, h):
    """Court gavel."""
    cv.line(x + 8, y + h - 10, x + w - 8, y + 10, (120, 72, 20), 5)
    cv.fill_rect(x + w // 2 - 16, y + 8, 32, 12, (120, 72, 20))
    cv.fill_rect(x + w // 2 - 20, y + 22, 40, 6, (90, 54, 14))
    cv.fill_rect(x + 6, y + h - 12, w - 12, 5, (90, 54, 14))


