def draw_featured(cv, x, y, w, st):
    ARTS[st["art"]](cv, x + 4, y, w - 8, 40)
    yy = y + 48
    draw_text(cv, x, yy + 13, st["kicker"], "sans_b", 13, RED)
    yy += 20
    for ln in wrap_text(st["headline"], "sans_b", 19, w)[:2]:
        draw_text(cv, x, yy + 19, ln, "sans_b", 19, INK)
        yy += 22
    yy += 2
    lines = wrap_text(st["body"], "sans", 14, w)[:4]
    for ln in lines:
        draw_text(cv, x, yy + 14, ln, "sans", 14, (40, 38, 32))
        yy += 16
    return yy


def build():
    cv = Canvas(_W, _H, PAPER)
    mx = 26
    cw = _W - 2 * mx
    # top rules + masthead
    cv.hline(mx, 14, cw, INK, 3)
    cv.hline(mx, 20, cw, INK, 1)
    draw_text(cv, _W // 2, 76, "THE WORLD TODAY", "serif_b", 54, INK,
              align="c")
    # date bar
    draw_text(cv, mx, 104, "TUESDAY, 24 NOVEMBER 2026", "sans_b", 16, INK)
    draw_text(cv, _W // 2, 104, "THE DAY’S NEWS IN ONE PAGE", "sans_b", 14,
              GREY, align="c")
    draw_text(cv, _W - mx, 104, "WORLD  •  24 NOV 2026", "sans_b", 14, GREY,
              align="r")
    cv.hline(mx, 112, cw, INK, 2)
    # lead story
    ly = 126
    draw_text(cv, mx, ly + 15, LEAD["kicker"], "sans_b", 15, RED)
    hy = ly + 24
    for ln in LEAD["headline"]:
        draw_text(cv, mx, hy + 40, ln, "serif_b", 40, INK)
        hy += 46
    dy = hy + 6
    dy = draw_para(cv, mx, dy, LEAD["deck"], "sans", 16, (40, 38, 32), 600)
    dy = draw_para(cv, mx, dy + 2, LEAD["deck2"], "sans", 16, (40, 38, 32),
                   600)
    # hero globe, right of the lead text
    gx, gy, gr = 812, 224, 88
    draw_globe(cv, gx, gy, gr)
    draw_text(cv, gx, gy + gr + 20, "THE SUMMIT ENDS", "sans_b", 13, INK,
              align="c")
    draw_text(cv, gx, gy + gr + 38, "WITH NO DEAL AT ALL", "sans_b", 13, RED,
              align="c")
    cv.hline(mx, 362, cw, INK, 2)
    # featured rows: 3 + 3
    col_w = (cw - 48) // 3
    for row in range(2):
        y0 = 374 + row * 190
        for i in range(3):
            x0 = mx + i * (col_w + 24)
            draw_featured(cv, x0, y0, col_w, FEATURED[row * 3 + i])
            if i < 2:
                cv.vline(x0 + col_w + 12, y0 + 4, 168, LIGHT, 1)
        cv.hline(mx, y0 + 182, cw, INK, 1)
    # briefs
    by = 762
    draw_text(cv, mx, by + 16, "THE DAY IN BRIEF", "sans_b", 16, INK)
    draw_text(cv, _W - mx, by + 16, "24 NOVEMBER 2026", "sans_b", 13, GREY,
              align="r")
    cv.hline(mx, by + 24, cw, INK, 2)
    bcol_w = (cw - 48) // 3
    for col in range(3):
        x0 = mx + col * (bcol_w + 24)
        yy = by + 30
        for tag, txt in BRIEFS[col * 8:(col + 1) * 8]:
            draw_text(cv, x0, yy + 13, "• ", "sans_b", 12, RED)
            tw = text_width("• ", "sans_b", 12)
            draw_text(cv, x0 + tw, yy + 13, tag + ": ", "sans_b", 12, RED)
            tw2 = tw + text_width(tag + ": ", "sans_b", 12)
            draw_text(cv, x0 + tw2, yy + 13, txt, "sans", 12, (40, 38, 32))
            yy += 19
    # ticker bar
